function normalizeEndpoint(value){return String(value||'').trim().replace(/\/+$/,'');}
function modelDraftFingerprint(draft){return JSON.stringify([draft.provider,normalizeEndpoint(draft.endpoint),draft.model,draft.credential_revision]);}
function createModelDraftGuard(){
 let revision=0,verified='',verifiedProof='',sequence=0;
 const fingerprint=draft=>modelDraftFingerprint({...draft,credential_revision:revision});
 return {revision:()=>revision,invalidate(){revision++;verified='';verifiedProof='';sequence++;},canApply:draft=>verified===fingerprint(draft)&&verifiedProof.length>=32,async test(draft,request,currentDraft){const proof=fingerprint(draft),run=++sequence;let result;try{result=await request(draft);}catch(error){if(run===sequence){verified='';verifiedProof='';}throw error;}if(run!==sequence||proof!==fingerprint(currentDraft()))return {accepted:false,stale:true,result};if(!result?.ok||typeof result.test_proof!=='string'||result.test_proof.length<32){verified='';verifiedProof='';return {accepted:false,stale:false,result};}verified=proof;verifiedProof=result.test_proof;return {accepted:true,stale:false,result};},async apply(draft,save){if(!this.canApply(draft))return false;const payload={...draft,test_proof:verifiedProof};delete payload.credential_revision;await save(payload);this.invalidate();return true;}};
}
// Owner-facing time: relative words for recent moments, the full date otherwise;
// the absolute time always travels with the node (title/datetime).
function formatTimeParts(value,now=Date.now()){if(!value)return {relative:t('시간 정보 없음'),absolute:'',iso:''};const date=new Date(value*1000),diff=(date.getTime()-now)/1000,abs=Math.abs(diff);let relative;if(abs<45)relative=t('방금');else if(abs<3600)relative=TIME_RELATIVE.format(Math.round(diff/60),'minute');else if(abs<86400)relative=TIME_RELATIVE.format(Math.round(diff/3600),'hour');else if(abs<86400*7)relative=TIME_RELATIVE.format(Math.round(diff/86400),'day');else relative=(date.getFullYear()===new Date(now).getFullYear()?TIME_DAY:TIME_YEAR).format(date);return {relative,absolute:TIME_ABSOLUTE.format(date),iso:date.toISOString()};}
// Formatted result text. The parser only produces a small set of block/inline
// kinds; the renderer builds nodes with textContent, so no HTML in a result
// can reach the document and only http(s) links become anchors.
function parseInline(text){const out=[],re=/(\*\*([^*\n]+)\*\*)|(`([^`\n]+)`)|(\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\))|(https?:\/\/[^\s<>()]+)/g;let last=0,match;while((match=re.exec(text))){if(match.index>last)out.push({type:'text',text:text.slice(last,match.index)});if(match[1])out.push({type:'strong',text:match[2]});else if(match[3])out.push({type:'code',text:match[4]});else if(match[5])out.push({type:'link',text:match[6],href:match[7]});else{const url=match[8].replace(/[.,;:!?)]+$/,'');out.push({type:'link',text:url,href:url});if(url.length<match[8].length)out.push({type:'text',text:match[8].slice(url.length)});}last=re.lastIndex;}if(last<text.length)out.push({type:'text',text:text.slice(last)});return out;}
function parseRichText(text){const blocks=[],lines=String(text||'').replace(/\r\n?/g,'\n').split('\n'),bullet=/^\s*[-*•]\s+/,numbered=/^\s*\d+[.)]\s+/,heading=/^#{1,6}\s+/,fence=/^\s*```/;let i=0;while(i<lines.length){const line=lines[i];if(!line.trim()){i++;continue;}if(fence.test(line)){const code=[];i++;while(i<lines.length&&!fence.test(lines[i]))code.push(lines[i++]);i++;blocks.push({type:'pre',text:code.join('\n')});continue;}if(heading.test(line)){blocks.push({type:'heading',inlines:parseInline(line.replace(heading,'').replace(/\s+#+\s*$/,''))});i++;continue;}if(bullet.test(line)||numbered.test(line)){const ordered=numbered.test(line),items=[];while(i<lines.length&&(bullet.test(lines[i])||numbered.test(lines[i])))items.push(parseInline(lines[i++].replace(bullet,'').replace(numbered,'')));blocks.push({type:'list',ordered,items});continue;}const para=[];while(i<lines.length&&lines[i].trim()&&!fence.test(lines[i])&&!heading.test(lines[i])&&!bullet.test(lines[i])&&!numbered.test(lines[i]))para.push(parseInline(lines[i++]));blocks.push({type:'paragraph',lines:para});}return blocks;}
// Owner words for internal tool ids. Unknown ids stay generic here and exact
// under technical details.
const TOOL_NAMES={subscription_engine:'구독 CLI 실행',model:'AI 응답',web_search:'웹 검색',list_notes:'메모 조회',save_note:'메모 저장',fixture:'점검 도구'};
function toolName(id){return t(TOOL_NAMES[id]||'도구 실행');}
function eventStatusText(status){return {succeeded:t('완료'),failed:t('실패'),running:t('실행 중')}[status]||t('관찰됨');}
function eventTone(status){return {succeeded:'ok',failed:'danger',running:'run'}[status]||'neutral';}
function taskTone(task){if(task.status_kind==='active')return 'run';if(['failed','interrupted'].includes(task.status))return 'danger';if(task.status==='cancelled')return 'neutral';if(task.status==='partial')return 'attention';if(task.delivery==='unknown')return 'unknown';if(task.status_kind==='finished')return 'ok';return 'attention';}
function outcomeTone(task,outcome){if(task.status==='cancelled')return 'neutral';if(outcome.kind==='attention')return ['failed','interrupted'].includes(task.status)?'danger':task.delivery==='unknown'&&task.status_kind!=='active'?'unknown':'attention';return task.status_kind==='active'?'run':'ok';}
// Relations come only from the task API (#557 continuity). Nothing is inferred here.
const RELATION_TEXT={retry:'다시 시도한 요청',reference:'이전 요청을 참조',cancel:'이전 요청을 취소',correction:'이전 요청을 정정'};
function relationText(kind){return t(RELATION_TEXT[kind]||'이전 요청과 연결됨');}
// Owner-readable trace from observed events. Consecutive transitions of one
// tool (running -> succeeded) collapse into one line; the closing line is the
// observed Work outcome, never an assumed success.
function semanticTrace(task){const steps=[];for(const event of task?.events||[]){const last=steps[steps.length-1];if(last&&last.tool===event.tool&&last.status==='running'){last.status=event.status;last.summary=event.summary;last.eventIds.push(event.id);continue;}steps.push({tool:event.tool,status:event.status,time:event.created,summary:event.summary,eventIds:[event.id]});}
 const rows=steps.map(step=>({time:step.time,text:step.status==='running'?t('{tool} 시작',{tool:toolName(step.tool)}):t('{tool} {status}',{tool:toolName(step.tool),status:eventStatusText(step.status)}),tone:eventTone(step.status),note:step.status==='failed'?t(step.summary):'',eventIds:step.eventIds}));
 if(task&&task.status_kind!=='active'&&!task.waits?.length)rows.push({time:task.observed_at,text:task.status==='succeeded'&&task.delivery!=='unknown'&&task.response?t('답변'):statusText(task),tone:taskTone(task),note:'',eventIds:[]});
 return rows;}
