function dayKey(value){if(!value)return 'unknown';const d=new Date(value*1000);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function dayLabel(value,now=Date.now()){if(!value)return t('시간 정보 없음');const day=new Date(value*1000),today=new Date(now);day.setHours(0,0,0,0);today.setHours(0,0,0,0);const diff=Math.round((day-today)/86400000);if(diff===0||diff===-1)return TIME_RELATIVE.format(diff,'day');return (day.getFullYear()===today.getFullYear()?TIME_DAY:TIME_YEAR).format(day);}
// #578: newest first. Takes turns in chronological order, keeps the most recent
// `limit`, and returns day groups (and turns within them) newest first. Days are
