// Owner-visible words for the four contract states.  An unknown value is
// reported as unknown rather than guessed as connected: a wrong 'connected'
// here would tell the owner an authorization exists that does not.
const CONNECTOR_STATES={disconnected:'연결 안 됨',connected:'연결됨',reauth_required:'다시 인증 필요',blocked:'차단됨'};
const CONNECTOR_NAMES={'google-gmail-read':'Google Gmail','google-calendar':'Google Calendar','google-calendar-write':'Google Calendar 일정 만들기','google-drive-read':'Google Drive'};
// What each connection lets AgentOS do, in owner words.  Read and create stay
// separate rows because they are separate authorities.
const CONNECTOR_PURPOSE={'google-gmail-read':'메일 검색과 읽기만 합니다. 보내지 않습니다.','google-calendar':'일정을 읽기만 합니다.','google-calendar-write':'일정을 만들기 전에 매번 확인을 받습니다.','google-drive-read':'Google Picker에서 고른 파일만 읽습니다.'};
const CONNECTOR_STATE_KINDS={connected:'active',disconnected:'neutral',reauth_required:'attention',blocked:'attention'};
function directRouteName(model){const provider=displayProvider(model),name=t(providerNames[provider]||provider);return provider==='openai'?'OpenAI Developer API':name;}
// The connect action is a plain same-origin navigation, not an api() call:
// /google-gmail answers 303 to Google, which fetch would follow cross-origin
// and discard.  The href stays relative so the owner-session cookie, which is
// SameSite=Strict and host-scoped, travels whether AgentOS was opened at
// 127.0.0.1 or localhost.  Drawing the link grants nothing; the route still
// requires that session and still refuses a tunnel host.
function connectorRowModel(connector){const id=String(connector?.connector_id||''),raw=String(connector?.state||''),known=Object.hasOwn(CONNECTOR_STATES,raw),backendLabel=String(connector?.label||'').trim(),name=CONNECTOR_NAMES[id]?t(CONNECTOR_NAMES[id]):(backendLabel&&backendLabel!==id?backendLabel:t('기타 연결')),purpose=CONNECTOR_PURPOSE[id]?t(CONNECTOR_PURPOSE[id]):'',connectable=Boolean(connector?.connect_path)&&known&&raw!=='blocked';let description;if(raw==='blocked')description=t('현재 정책으로 사용할 수 없습니다.');else if(!known)description=t('연결 상태를 확인하지 못했습니다. 연결됐다고 가정하지 않습니다.');else if(raw!=='connected'&&!connector?.connect_path&&connector?.connect_hint)description=[purpose,t(connector.connect_hint)].filter(Boolean).join(' ');else description=purpose||t('연결 상태와 권한을 확인합니다.');const lines=[t('연결 ID: {id}',{id:id||t('정보 없음')}),t('상태 값: {state}',{state:raw||t('정보 없음')}),t('요청 권한: {scopes}',{scopes:(connector?.required_scopes||[]).join(', ')||t('요청 권한 없음')})];if(connector?.detail_state&&connector.detail_state!==raw)lines.push(t('세부 상태: {state}',{state:connector.detail_state}));return {id,name,description,state:t(known?CONNECTOR_STATES[raw]:'확인 필요'),kind:known?CONNECTOR_STATE_KINDS[raw]:'attention',action:connectable?(raw==='disconnected'?t('연결'):t('다시 연결')):'',href:connectable?connector.connect_path:'',lines};}
function renderConnectors(connectors){const box=$('connector-controls');if(!box)return;const rows=connectors||[],fingerprint=JSON.stringify(rows);if(box.dataset.state===fingerprint)return;box.dataset.state=fingerprint;box.replaceChildren();for(const connector of rows){const view=connectorRowModel(connector);let action=null;if(view.href){const link=element('a',view.action,'button-link settings-row-action');link.href=view.href;link.rel='noreferrer';action=link;}box.append(settingsRow(view.name,view.description,view.state,view.kind,action,settingsDisclosure(t('세부 정보'),view.lines)));}if(!rows.length)box.append(element('p',t('이 설치에는 연결할 수 있는 Google 서비스가 없습니다. Google 연결은 설치에 커넥터가 포함돼 있을 때 여기에 나타납니다.'),'settings-empty'));}
