function renderDiagnostics(state,tasks){const events=(state?.tool_events||[]).slice(0,20),hidden=(tasks||[]).filter(isDiagnosticTask).length,fingerprint=JSON.stringify([events,hidden]),list=$('tool-history');if(list.dataset.state===fingerprint)return;list.dataset.state=fingerprint;const current=events[0];$('tool-status').textContent=current?t('최근: {tool} {status}',{tool:toolName(current.tool),status:eventStatusText(current.status)}):t('관찰된 도구 활동이 없습니다.');list.replaceChildren();for(const event of events){const row=element('div',undefined,'record-row'),text=element('span');text.append(element('span',toolName(event.tool)),' ',badge(eventStatusText(event.status),eventTone(event.status)),' ',element('span',`(${event.tool})`,'technical'));row.append(text,timeNode(event.created));list.append(row);}$('diagnostic-activity').textContent=t('작업 목록에서 분리한 연결 확인 및 진단 활동 {count}개',{count:hidden});}

async function refresh(){
 if(!authenticated)return;if(refreshing){refreshQueued=true;return;}refreshing=true;const requestedModelRevision=modelLoadRevision,requestedRootsRevision=rootsLoadRevision,requestedFileWorkspaceRevision=fileWorkspaceLoadRevision;$('task-refresh-state').textContent=t('확인 중…');
 try{
  const [summary,home,state,space]=await Promise.all([api('/api/tasks'),api('/api/home'),api('/api/state'),api('/api/personal-space')]);const previousTasks=new Map((taskProgress?.tasks||[]).map(task=>[task.id,task]));lastHome=home;lastState=state;lastSpace=space;taskProgress=mergeTaskProgress(summary,taskProgress,state.jobs);renderTasks();for(const id of new Set([...openTraces,...openTechnical])){const before=previousTasks.get(id),after=taskProgress.tasks.find(task=>task.id===id);void refreshSelectedTaskDetail(before,after,loadTaskDetail);}renderRecords();renderMemoryCandidateSummary(space);if(activeView==='records')void refreshLoadedRecords();renderWorkspaces(home,state);loadWorkspaceResultSummaries(home.workspaces);
  const settings=state.settings||{};renderExecutionConnection(settings);renderDecisionRoute(settings);renderSubscriptionEngines(settings.subscription_engines);renderTelegram(settings);renderConnectors(settings.connectors);renderContext(settings.context_inbox);renderDocumentBoundary(settings.document_boundary);renderDiagnostics(state,taskProgress.tasks);const runtime=$('runtime-badge');const runtimeState=home.state==='working'?['작업 중','run']:home.state==='attention'?['확인 필요','attention']:home.state==='ready'?(home.model_connected?['준비됨','ok']:['AI 연결 안 됨','attention']):['상태 알 수 없음','unknown'];runtime.textContent=t(runtimeState[0]);runtime.className='badge '+runtimeState[1];document.body.classList.remove('offline');$('nav-settings-dot').classList.toggle('on',[...document.querySelectorAll('#view-settings .settings-row>.settings-state.attention')].some(node=>!node.closest('.folder-edit')&&!node.parentElement.querySelector('.settings-inline-confirm')));lastSuccessfulRefresh=Date.now();
  if(!modelLoaded){if(requestedModelRevision===modelLoadRevision){const model=settings.model||{};if(model.provider){$('provider').value=displayProvider(model);$('endpoint').value=model.endpoint||'';$('model-name').value=model.model||'';activeModelDestination=[displayProvider(model),normalizeEndpoint(model.endpoint)].join('|');}$('endpoint-help').textContent=t(providers[$('provider').value]?.help||'');$('key-hint').textContent=settings.has_api_key?t('키가 저장되어 있습니다. 빈칸은 같은 연결의 키를 유지합니다.'):t('키는 대화 이력과 분리해 저장합니다.');modelLoaded=true;}}
  if(requestedRootsRevision===rootsLoadRevision)renderRootList(settings.file_roots||[]);
  if(requestedFileWorkspaceRevision===fileWorkspaceLoadRevision)renderFileWorkspace(settings.file_workspace);
  void loadFolderRequests();
  $('task-refresh-state').textContent=t('방금 확인');setFeedback('global-error','');
 }catch(error){const offline=Boolean(error?.offline);setError('global-error',offline&&lastSuccessfulRefresh?new Error(`${t(OFFLINE_MESSAGE)} ${t('마지막 확인: {time}.',{time:formatTimeParts(lastSuccessfulRefresh/1000).relative})}`):error);$('task-refresh-state').textContent=t('새로 고치지 못함');if(offline){const runtime=$('runtime-badge');runtime.textContent=t('연결 끊김');runtime.className='badge unknown';document.body.classList.add('offline');$('nav-task-count').dataset.count='0';$('nav-task-count').replaceChildren();}}finally{refreshing=false;if(refreshQueued){refreshQueued=false;void refresh();}}
}

async function status(){
 let state=await api('/api/status');if(!state.claimed){await api('/api/claim',{code:bootstrap});state=await api('/api/status');}claimed=state.claimed;authenticated=state.authenticated;if(!authenticated&&state.local_access){await api('/api/local-login',{});authenticated=true;}
 $('welcome').hidden=authenticated;$('management').hidden=!authenticated;$('logout').hidden=!authenticated||state.local_access;$('auth-title').textContent=claimed?t('다시 만나서 반갑습니다.'):t('나만의 AgentOS를 시작하세요.');$('password-hint').textContent=claimed?'':t('12자 이상으로 정하세요.');setFeedback('auth-error','');$('auth-help').textContent=claimed?t('설정한 비밀번호로 로그인하세요.'):t('이 Mac에서 사용할 개인 환경을 준비합니다.');$('auth-submit').textContent=claimed?t('로그인'):t('바로 시작하기');$('password').required=claimed;$('password-option').open=claimed;$('password').minLength=claimed?1:12;$('password').autocomplete=claimed?'current-password':'new-password';
 if(authenticated){const route=routeFromLocation();activeView=route.view;activeSettings=route.settings;navigate(activeView,activeSettings,{replace:true});restoreOpenRouterFlow();await refresh();await loadRecords();await finishOpenRouter();}
}
